const address = query("path", { ...string, default: "" }, "Canonical workspace-relative POSIX path. Empty selects the root for directory operations.")
const fileAddress = { ...address, required: true, schema: { ...string, minLength: 1 } }
const cursor = query("cursor", string, "Opaque cursor bound to a retained metadata view, workspace epoch, scope, and query.")
const sizeBudget = (name, limit, fallback) => ({ ...query(name, { type: "integer", minimum: 1 }, "Positive integer within the advertised deployment ceiling."), limit, fallback })
const pageLimit = sizeBudget("limit", "pageMaxSize", "pageSize")
