function effectiveLimits(overrides) {
	return { ...FILE_LIMITS, treeEntries: 5000, treeMaxEntries: 50000, searchMaxElapsedMs: overrides?.elapsedMs ?? FILE_LIMITS.elapsedMs, ...overrides }
}

