const jsonContent = (schema) => ({ "application/json": { schema: ref(schema) } })
const responseHeaders = {
	ETag: { schema: string, description: "Weak observation validator for live bytes, strong representation validator for protected bytes." },
	"Accept-Ranges": { schema: { type: "string", const: "bytes" } },
	"Content-Length": { schema: integer },
	"Content-Encoding": { schema: { type: "string", const: "identity" } },
	"Content-Disposition": { schema: string, description: "Safe ASCII filename plus UTF-8 filename*. Active content is attachment." },
	"Last-Modified": { schema: string, description: "HTTP date when available. Live dates do not establish a strong validator." },
}

